{"file_path":"src/diff.js","content":"/**
 * Line diffing: longest common subsequence over whole lines, compared as exact
 * strings, with ties resolved in favour of the matches that come earliest.
 */

/**
 * Longest common subsequence of two line arrays.
 *
 * Returns the matched pairs as `{ side, base }` index pairs, in order.
 *
 * The walk starts at the beginning of both documents: a match is taken
 * whenever the two current lines are equal, and otherwise the side whose
 * remaining subsequence is at least as long as the other's is advanced, the
 * base winning the tie.
 */
export function longestCommonSubsequence(side, base) {
  const n = side.length
  const m = base.length

  // table[i][j] is the length of the longest common subsequence of the
  // suffixes side[i..] and base[j..].
  const table = []
  for (let i = 0; i <= n; i++) table.push(new Int32Array(m + 1))

  for (let i = n - 1; i >= 0; i--) {
    const row = table[i]
    const next = table[i + 1]
    for (let j = m - 1; j >= 0; j--) {
      row[j] = side[i] === base[j] ? next[j + 1] + 1 : Math.max(next[j], row[j + 1])
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (side[i] === base[j]) {
      matches.push({ side: i, base: j })
      i++
      j++
    } else if (table[i][j + 1] >= table[i + 1][j]) {
      j++
    } else {
      i++
    }
  }
  return matches
}

/**
 * The changes one side makes to the base: every stretch the common
 * subsequence does not cover, as a run of base lines replaced by a run of the
 * side's lines.
 */
export function changesAgainstBase(side, base) {
  const matches = longestCommonSubsequence(side, base)
  const changes = []
  let sidePos = 0
  let basePos = 0

  const emit = (sideEnd, baseEnd) => {
    if (sidePos < sideEnd || basePos < baseEnd) {
      changes.push({ baseStart: basePos, baseEnd, sideStart: sidePos, sideEnd })
    }
  }

  for (const match of matches) {
    emit(match.side, match.base)
    sidePos = match.side + 1
    basePos = match.base + 1
  }
  emit(side.length, base.length)

  return changes
}
"}

