{"file_path":"src/merge.js","content":"/**
 * The three-way merge itself: the changes of both sides against the base are
 * gathered into regions, and every region is resolved or reported as a
 * conflict.
 */

import { changesAgainstBase } from './diff.js'

function sameLines(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * The lines one side puts in place of the base lines of a region.
 *
 * A side that changed nothing inside the region simply keeps the base lines.
 * Otherwise the replacement runs from the smallest start of that side's
 * changes, moved back by however far the region begins before those changes
 * do in the base, to the largest end of its own changes, moved forward by
 * however far the region ends after them.
 */
function replacementFor(document, base, changes, regionStart, regionEnd) {
  if (changes.length === 0) return base.slice(regionStart, regionEnd)

  let sideStart = changes[0].sideStart
  let sideEnd = changes[0].sideEnd
  let baseStart = changes[0].baseStart
  let baseEnd = changes[0].baseEnd
  for (const change of changes) {
    if (change.sideStart < sideStart) sideStart = change.sideStart
    if (change.sideEnd > sideEnd) sideEnd = change.sideEnd
    if (change.baseStart < baseStart) baseStart = change.baseStart
    if (change.baseEnd > baseEnd) baseEnd = change.baseEnd
  }

  return document.slice(sideStart - (baseStart - regionStart), sideEnd + (regionEnd - baseEnd))
}

function resolve(mineLines, baseLines, theirsLines) {
  if (sameLines(mineLines, theirsLines)) return { kind: 'both', lines: mineLines }
  if (sameLines(mineLines, baseLines)) return { kind: 'theirs', lines: theirsLines }
  if (sameLines(theirsLines, baseLines)) return { kind: 'mine', lines: mineLines }
  return { kind: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines }
}

/**
 * The regions of a merge, in base order: stable stretches the merge keeps
 * unchanged, resolved changes and conflicts.
 */
export function mergeRegions(mine, base, theirs) {
  const changes = []
  for (const change of changesAgainstBase(mine, base)) changes.push({ ...change, from: 'mine' })
  for (const change of changesAgainstBase(theirs, base)) changes.push({ ...change, from: 'theirs' })
  changes.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.from === b.from) return 0
    return a.from === 'mine' ? -1 : 1
  })

  const regions = []
  let taken = 0
  let index = 0

  while (index < changes.length) {
    const first = changes[index++]
    const regionStart = first.baseStart
    let regionEnd = first.baseEnd
    const touching = [first]
    while (index < changes.length && changes[index].baseStart <= regionEnd) {
      const next = changes[index++]
      touching.push(next)
      if (next.baseEnd > regionEnd) regionEnd = next.baseEnd
    }

    if (taken < regionStart) {
      regions.push({ kind: 'stable', lines: base.slice(taken, regionStart) })
    }

    const mineChanges = touching.filter(change => change.from === 'mine')
    const theirsChanges = touching.filter(change => change.from === 'theirs')

    if (touching.length === 1) {
      const only = touching[0]
      regions.push({ kind: only.from, lines: (only.from === 'mine' ? mine : theirs).slice(only.sideStart, only.sideEnd) })
    } else {
      regions.push(resolve(
        replacementFor(mine, base, mineChanges, regionStart, regionEnd),
        base.slice(regionStart, regionEnd),
        replacementFor(theirs, base, theirsChanges, regionStart, regionEnd),
      ))
    }

    taken = regionEnd
  }

  if (taken < base.length) regions.push({ kind: 'stable', lines: base.slice(taken) })

  return regions
}
"}

