{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of mine and theirs over the base they share.
 */

import { readFileSync, writeSync } from 'node:fs'
import { mergeRegions } from './merge.js'

const MODES = ['merge', 'merge2', 'regions']
const SEPARATOR = '%%%'

function fail(message) {
  writeSync(2, `error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

/** The three documents the input holds, as arrays of lines. */
function parseDocuments(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const documents = [[]]
  for (const line of lines) {
    if (line === SEPARATOR) documents.push([])
    else documents[documents.length - 1].push(line)
  }
  return documents
