/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import * as readline from 'readline';

// Parse arguments
const mode = process.argv[2];
if (!['merge', 'merge2', 'regions'].includes(mode)) {
  process.stderr.write('error: usage: cli.js merge|merge2|regions\n');
  process.exit(2);
}

// Read input from stdin
let input = '';
const rl = readline.createInterface({ input: process.stdin });

rl.on('line', (line) => {
  input += line + '\n';
});

rl.on('close', () => {
  try {
    processInput(input);
  } catch (err) {
    process.stderr.write(`error: ${err.message}\n`);
    process.exit(2);
  }
});

function processInput(input) {
  // Parse documents
  const parts = input.split('%%%\n');
  if (parts.length !== 3) {
    throw new Error('expected three parts separated by %%%');
  }

  // Parse each document
  const parseDoc = (part) => {
    if (part === '' || part === '\n') return [];
    const lines = part.split('\n');
    if (lines[lines.length - 1] === '') {
      lines.pop();
    }
    return lines;
  };

  const mine = parseDoc(parts[0]);
  const base = parseDoc(parts[1]);
  const theirs = parseDoc(parts[2]);

  // Compute changes for each side vs base
  const mineChanges = computeChanges(mine, base);
  const theirsChanges = computeChanges(theirs, base);

  // Merge and output result
  const { output, hasConflict } = performMerge(mine, base, theirs, mineChanges, theirsChanges, mode);
  process.stdout.write(output);
  process.exit(hasConflict ? 1 : 0);
}

// Compute LCS with early-match preference
function computeLCS(a, b) {
  const n = a.length;
  const m = b.length;

  // Build DP table for LCS length
  const dp = Array(n + 1).fill(null).map(() => Array(m + 1).fill(0));

  for (let i = 1; i <= n; i++) {
    for (let j = 1; j <= m; j++) {
      if (a[i - 1] === b[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
      }
    }
  }

  // Reconstruct LCS with early-match preference
  const lcs = [];
  let i = n;
  let j = m;

  while (i > 0 && j > 0) {
    if (a[i - 1] === b[j - 1]) {
      lcs.unshift({ i: i - 1, j: j - 1 });
      i--;
      j--;
    } else {
      // When sequences are equally long, advance the side with at least as long remaining
      // Prefer to advance base (j) when they tie
      if (j > i) {
        j--;
      } else {
        i--;
      }
    }
  }

  return lcs;
}

// Convert LCS to list of changes
function computeChanges(side, base) {
  const lcs = computeLCS(side, base);
  const changes = [];

  let lastSidePos = 0;
  let lastBasePos = 0;

  for (const { i, j } of lcs) {
    // Create a change for the gap before this match if there is a gap
    if (lastSidePos < i || lastBasePos < j) {
      changes.push({
        baseStart: lastBasePos,
        baseEnd: j,
        sideStart: lastSidePos,
        sideEnd: i,
        side: side.slice(lastSidePos, i)
      });
    }
    lastSidePos = i + 1;
    lastBasePos = j + 1;
  }

  // Handle trailing gap if there is one
  if (lastSidePos < side.length || lastBasePos < base.length) {
    changes.push({
      baseStart: lastBasePos,
      baseEnd: base.length,
      sideStart: lastSidePos,
      sideEnd: side.length,
      side: side.slice(lastSidePos)
    });
  }

  return changes;
}

// Perform the three-way merge
function performMerge(mine, base, theirs, mineChanges, theirsChanges, mode) {
  // Merge the change lists
  const allChanges = [];

  mineChanges.forEach(change => {
    allChanges.push({ ...change, source: 'mine' });
  });

  theirsChanges.forEach(change => {
    allChanges.push({ ...change, source: 'theirs' });
  });

  // Sort by base start position, with mine before theirs when equal
  allChanges.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart;
    return a.source === 'mine' ? -1 : 1;
  });

  // Process regions
  const regions = [];
  let lastBaseEnd = 0;

  while (allChanges.length > 0) {
    const firstChange = allChanges.shift();
    let regionBaseStart = firstChange.baseStart;
    let regionBaseEnd = firstChange.baseEnd;
    const touchingChanges = [firstChange];

    // Absorb overlapping changes
    while (allChanges.length > 0 && allChanges[0].baseStart <= regionBaseEnd) {
      const nextChange = allChanges.shift();
      touchingChanges.push(nextChange);
      regionBaseEnd = Math.max(regionBaseEnd, nextChange.baseEnd);
    }

    // Add stable region before if needed
    if (lastBaseEnd < regionBaseStart) {
      regions.push({
        type: 'stable',
        lines: base.slice(lastBaseEnd, regionBaseStart)
      });
    }

    // Separate changes by source
    const mineInRegion = touchingChanges.filter(c => c.source === 'mine');
    const theirsInRegion = touchingChanges.filter(c => c.source === 'theirs');

    // Resolve the region
    if (mineInRegion.length === 0) {
      // Only theirs changed
      regions.push({
        type: 'theirs',
        lines: assembleReplacement(theirsInRegion)
      });
    } else if (theirsInRegion.length === 0) {
      // Only mine changed
      regions.push({
        type: 'mine',
        lines: assembleReplacement(mineInRegion)
      });
    } else {
      // Both sides changed - resolve conflict
      const mineLines = assembleReplacement(mineInRegion);
      const theirsLines = assembleReplacement(theirsInRegion);
      const baseLines = base.slice(regionBaseStart, regionBaseEnd);

      if (arraysEqual(mineLines, theirsLines)) {
        regions.push({
          type: 'both',
          lines: mineLines
        });
      } else if (arraysEqual(mineLines, baseLines)) {
        regions.push({
          type: 'theirs',
          lines: theirsLines
        });
      } else if (arraysEqual(theirsLines, baseLines)) {
        regions.push({
          type: 'mine',
          lines: mineLines
        });
      } else {
        regions.push({
          type: 'conflict',
          mine: mineLines,
          base: baseLines,
          theirs: theirsLines
        });
      }
    }

    lastBaseEnd = regionBaseEnd;
  }

  // Add final stable region if needed
  if (lastBaseEnd < base.length) {
    regions.push({
      type: 'stable',
      lines: base.slice(lastBaseEnd)
    });
  }

  // Generate output based on mode
  let output = '';
  let hasConflict = false;

  if (mode === 'merge' || mode === 'merge2') {
    regions.forEach(region => {
      if (region.type === 'stable') {
        output += region.lines.map(l => l + '\n').join('');
      } else if (region.type === 'mine') {
        output += region.lines.map(l => l + '\n').join('');
      } else if (region.type === 'theirs') {
        output += region.lines.map(l => l + '\n').join('');
      } else if (region.type === 'both') {
        output += region.lines.map(l => l + '\n').join('');
      } else if (region.type === 'conflict') {
        hasConflict = true;
        output += '<<<<<<< mine\n';
        output += region.mine.map(l => l + '\n').join('');
        if (mode === 'merge') {
          output += '||||||| base\n';
          output += region.base.map(l => l + '\n').join('');
        }
        output += '=======\n';
        output += region.theirs.map(l => l + '\n').join('');
        output += '>>>>>>> theirs\n';
      }
    });
  } else if (mode === 'regions') {
    regions.forEach(region => {
      if (region.type === 'stable') {
        output += `stable ${region.lines.length}\n`;
      } else if (region.type === 'mine') {
        output += `mine ${region.lines.length}\n`;
      } else if (region.type === 'theirs') {
        output += `theirs ${region.lines.length}\n`;
      } else if (region.type === 'both') {
        output += `both ${region.lines.length}\n`;
      } else if (region.type === 'conflict') {
        hasConflict = true;
        output += `conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}\n`;
      }
    });
  }

  return { output, hasConflict };
}

// Helper to assemble replacement lines from changes
function assembleReplacement(changes) {
  const result = [];
  for (const change of changes) {
    result.push(...change.side);
  }
  return result;
}

// Helper to compare arrays
function arraysEqual(a, b) {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false;
  }
  return true;
}

